
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_pbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_pbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.416958125158813e-02, -6.312637736668299e-02, -6.163072233894362e-02, -5.948951637066163e-02, -5.643118778016672e-02, -5.208083175960158e-02, -4.594653522692631e-02, -3.748907233609396e-02, -2.658496844366860e-02, -1.528083768195486e-02, -1.095404237240699e-02, -3.779802773627156e-02, -4.590656474082939e-02, -3.174838179497580e-02, -1.579091729042589e-02, -3.671461516355224e-03, -2.020554611935548e-04, -1.843127259464262e-06, -1.891836399894985e-09, -7.487108222160674e-14]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


